const body = $input.first().json.body || {};
const input = body.input || {};

let pkgs = [];
if (Array.isArray(input.packages)) {
  pkgs = input.packages;
} else if (input.dependencies && typeof input.dependencies === 'object') {
  // A package.json dependencies block, pasted whole. Ranges are stripped to a
  // concrete version, because "is ^4.17.20 safe" is not a question anyone can
  // answer: the range covers versions that differ in exactly the way that
  // matters.
  pkgs = Object.entries(input.dependencies).map(([name, range]) => ({
    name,
    version: String(range).replace(/^[\^~>=<\s]+/, ''),
    ecosystem: input.ecosystem || 'npm',
  }));
}

pkgs = pkgs
  .filter((p) => p && p.name && p.version)
  .map((p) => ({
    name: String(p.name),
    version: String(p.version),
    ecosystem: String(p.ecosystem || input.ecosystem || 'npm'),
  }))
  // Lower than the OSV worker's 100 on purpose. This one spends a model's
  // attention per package rather than a row lookup, and quality falls off well
  // before a context limit does.
  .slice(0, 40);

if (!pkgs.length) {
  throw new Error('Send {"input":{"packages":[{"name","version","ecosystem"}]}} or {"input":{"dependencies":{...}}}');
}

// Whatever model this seller's account actually has. This is the one line to
// change; everything downstream reads it back rather than assuming.
const MODEL = 'claude-sonnet-4-5';

const system = [
  'You are a dependency risk reviewer. You assess named package versions for known',
  'security advisories, maintenance risk, and upgrade urgency.',
  '',
  'Reply with a single JSON object and nothing else. No prose, no markdown fence.',
  '',
  'Schema:',
  '{',
  '  "assessed": [',
  '    {',
  '      "package": string,',
  '      "version": string,',
  '      "knownAdvisories": [{ "id": string, "summary": string, "fixedIn": string | null }],',
  '      "severity": "none" | "low" | "medium" | "high" | "critical",',
  '      "maintenanceRisk": string,',
  '      "recommendation": string,',
  '      "confidence": "high" | "medium" | "low"',
  '    }',
  '  ]',
  '}',
  '',
  'Rules:',
  '- Return exactly one entry per package given, in the same order. Never omit one.',
  '- Only list an advisory you actually know. Never invent an identifier; a wrong',
  '  CVE number is worse than none, because it will be believed.',
  '- If you are unsure whether a version is affected, use severity "none" with',
  '  confidence "low" and say why in recommendation. Silence is not safety, and a',
  '  buyer acting on a false all-clear is the failure mode that matters here.',
  '- Your training data has a cutoff. Advisories published after it are invisible',
  '  to you. Say so in recommendation for any widely used package.',
  '- maintenanceRisk is about the project, not the CVE: release cadence, whether it',
  '  is archived or superseded, single-maintainer exposure, install-time scripts.',
  '  This is the part a live advisory feed cannot tell anyone.',
].join('\n');

const user = 'Assess these dependencies:\n' + JSON.stringify(pkgs, null, 2);

return [{ json: {
  pkgs,
  model: MODEL,
  requestBody: {
    model: MODEL,
    max_tokens: 4096,
    temperature: 0,
    system,
    messages: [{ role: 'user', content: user }],
  },
} }];

const res = $input.first().json;
const built = $('Build request').first().json;
const pkgs = built.pkgs;

// Everything below refuses rather than degrades. A review worker that answers
// "nothing found" when the model failed, drifted off-schema, or skipped half the
// list is selling a clean bill of health for a question it never asked. That is
// the one failure a buyer cannot detect from the outside, so it has to be
// impossible from the inside.

if (res && res.type === 'error') {
  throw new Error('Anthropic returned an error: ' + JSON.stringify(res.error || res).slice(0, 300));
}

const parts = Array.isArray(res.content) ? res.content : null;
if (!parts) {
  throw new Error('Anthropic did not return a message: ' + JSON.stringify(res).slice(0, 300));
}
if (res.stop_reason === 'max_tokens') {
  throw new Error('The model hit max_tokens and its JSON is truncated. Send fewer packages.');
}

const text = parts.filter((p) => p && p.type === 'text').map((p) => p.text).join('').trim();

// Models fence JSON even when told not to. Strip one fence rather than failing
// on a response that is otherwise perfectly good.
const unfenced = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();

let parsed;
try {
  parsed = JSON.parse(unfenced);
} catch (e) {
  throw new Error('The model did not return JSON. First 300 chars: ' + unfenced.slice(0, 300));
}

const assessed = parsed.assessed;
if (!Array.isArray(assessed)) {
  throw new Error('The model returned JSON without an "assessed" array: ' + unfenced.slice(0, 300));
}

// Order is not trusted; membership is. A model that quietly drops a package
// would otherwise produce a shorter, cleaner-looking report.
const seen = new Set(assessed.map((a) => String((a && a.package) || '').toLowerCase()));
const missing = pkgs.filter((p) => !seen.has(p.name.toLowerCase())).map((p) => p.name);
if (missing.length) {
  throw new Error('The model skipped ' + missing.length + ' package(s): ' + missing.join(', '));
}

const LEVELS = ['none', 'low', 'medium', 'high', 'critical'];
const findings = assessed.filter((a) => {
  const sev = String((a && a.severity) || 'none').toLowerCase();
  const adv = Array.isArray(a && a.knownAdvisories) ? a.knownAdvisories : [];
  return adv.length > 0 || (LEVELS.indexOf(sev) > 0);
});

// Low confidence is a finding of its own. "I am not sure this is clean" is
// information the buyer paid for and must not be filtered out of the summary.
const unsure = assessed.filter((a) => String((a && a.confidence) || '').toLowerCase() === 'low');

return [{ json: { output: {
  scanned: pkgs.length,
  flagged: findings.length,
  lowConfidence: unsure.length,
  findings,
  assessed,
  method: 'llm-review',
  model: built.model,
  source: 'model knowledge, not a live advisory feed',
  caveat: 'This is a language model\'s judgement, bounded by its training cutoff. ' +
    'It can reason about maintenance and supply-chain risk that no feed encodes, ' +
    'and it can miss an advisory published after that cutoff. Pair it with a live ' +
    'feed scan for completeness; neither one alone is a full answer.',
  tokens: res.usage || null,
  checkedAt: new Date().toISOString(),
} } }];
